const MISSION_EVENTS=[{id:"stage1",text:"Resuscitation Room Prepared"},{id:"stage2",text:"ECG Rhythm Analyzed"},{id:"stage3",text:"Defibrillator Restored"},{id:"stage4",text:"Patient Stabilized"}];let completedMissions=[];function completeMission(n){completedMissions.includes(n)||(completedMissions.push(n),renderMissionLog())}function renderMissionLog(){const n=document.getElementById("mission-events");n&&(n.innerHTML=MISSION_EVENTS.map((n=>{const e=completedMissions.includes(n.id);return`\n\n\n            <div class="mission-event \n            ${e?"done":""}">\n\n\n                ${e?"✅":"⏳"}\n\n                ${n.text}\n\n\n            </div>\n\n\n            `})).join(""))}